export async function deleteLabel(
  actor: Actor,
  orgId: OrgId,
  labelId: LabelId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "project:archive", orgResource(orgId));
  await labelRepo.deleteLabel(orgId, labelId);
}

/**
 * Folds `sourceLabelId` into `targetLabelId`: every issue carrying the source
 * label ends up carrying the target instead, and the source label is gone
 * afterwards. Same blast radius as `deleteLabel`, so it takes the same
 * permission.
 */
export async function mergeLabels(
  actor: Actor,
  input: MergeLabelsInput,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:archive", orgResource(input.orgId));

  if (input.sourceLabelId === input.targetLabelId) {
    throw new Error("Cannot merge a label into itself");
  }

  const source = requireFound(
    await labelRepo.findLabelById(input.orgId, input.sourceLabelId),
    "Label",
    input.sourceLabelId,
  );
  const target = requireFound(
    await labelRepo.findLabelById(input.orgId, input.targetLabelId),
    "Label",
    input.targetLabelId,
  );

  const issuesRelabelled = await labelRepo.mergeLabels(
    input.orgId,
    source.id,
    target.id,
  );

  return { label: target, issuesRelabelled };
}

